t.script:
                // Template data
                var templateId = ;
                var templateName = '';
                var variableBlocks = ;

                // Initialize GrapesJS
                var editor = grapesjs.init({
                    container: '#grapesjs-editor',
                    height: '100vh',
                    width: 'auto',

                    // Storage Manager - Save to Odoo backend
                    storageManager: {
                        type: 'remote',
                        autosave: true,
                        autoload: true,
                        stepsBeforeSave: 3,

                        urlStore: '/contract/template/save',
                        urlLoad: '/contract/template/load/' + templateId,

                        headers: {
                            'Content-Type': 'application/json',
                        },

                        onStore: function(data) {
                            return {
                                template_id: templateId,
                                html: editor.getHtml(),
                                css: editor.getCss(),
                                components: JSON.stringify(data.components),
                                styles: JSON.stringify(data.styles),
                            };
                        },
                    },

                    // Plugins
                    plugins: ['gjs-preset-webpage'],
                    pluginsOpts: {
                        'gjs-preset-webpage': {
                            blocks: ['column1', 'column2', 'column3', 'text', 'link', 'image', 'video', 'map'],
                        }
                    },

                    // Canvas settings
                    canvas: {
                        styles: [
                            'https://maxcdn.bootstrapcdn.com/bootstrap/4.5.2/css/bootstrap.min.css',
                        ],
                    },

                    // Block Manager
                    blockManager: {
                        appendTo: '.gjs-blocks-c',
                        blocks: variableBlocks.concat([
                            // Custom contract blocks
                            {
                                id: 'section',
                                label: 'Section',
                                category: 'Layout',
                                content: '

Section Title
Content...',
                            },
                            {
                                id: 'article',
                                label: 'Article',
                                category: 'Contract',
                                content: '

ARTICLE X - Title
Article content...',
                            },
                            {
                                id: 'signature-block',
                                label: 'Signature Block',
                                category: 'Contract',
                                content: `





For the Main Contractor

Name and Signature:







For the Subcontractor

Electronic Signature





                                `,
                            },
                        ]),
                    },

                    // Layer Manager
                    layerManager: {
                        appendTo: '.gjs-pn-views-container',
                    },

                    // Style Manager
                    styleManager: {
                        appendTo: '.gjs-sm-sectors',
                        sectors: [
                            {
                                name: 'Dimension',
                                open: false,
                                buildProps: ['width', 'min-height', 'padding', 'margin'],
                            },
                            {
                                name: 'Typography',
                                open: false,
                                buildProps: ['font-family', 'font-size', 'font-weight', 'letter-spacing', 'color', 'line-height', 'text-align'],
                            },
                            {
                                name: 'Decorations',
                                open: false,
                                buildProps: ['background-color', 'border', 'border-radius', 'box-shadow'],
                            },
                        ],
                    },
                });

                // Add custom commands
                editor.Commands.add('show-json', {
                    run: function(editor, sender) {
                        sender && sender.set('active', 0);
                        alert(JSON.stringify(editor.getComponents(), null, 2));
                    }
                });

                // Add panels
                editor.Panels.addButton('options', {
                    id: 'save-template',
                    className: 'fa fa-save',
                    command: 'core:canvas-clear',
                    attributes: { title: 'Save Template' },
                });
